def kl_error(self, input_data, targets, average=True,
                 cache=None, prediction=True):
        """ The KL divergence error
        """
        if cache is None:
            cache = {}

        if prediction:
            input_data = self.predict(input_data)

        if self.log_input:
            input_data = torch.log(input_data)

        if self.log_targets:
            targets = torch.log(targets)

        if self.reduction == 'none':
            return torch.sum(torch.sum(input_data * targets, dim=1), dim=0)
        elif self.reduction == 'mean':
            return torch.mean(torch.mean(input_data * targets, dim=1), dim=0)
        elif self.reduction == 'sum':
            return torch.sum(torch.sum(input_data * targets, dim=1), dim=0)
        else:
            raise ValueError('Invalid reduction mode')

